style.DraftEditForm:
/* Shared with ChatView's other cards, so COPIED here (ChatView keeps its own): the
   form's inputs and the visually-hidden header label. Same declarations, same order. */
/* visually-hidden live region for screen-reader announcements (UX #5) */
.jv-sr {
	position: absolute;
	width: 1px;
	height: 1px;
	margin: -1px;
	padding: 0;
	border: 0;
	overflow: hidden;
	clip: rect(0 0 0 0);
	clip-path: inset(50%);
	white-space: nowrap;
}
.jv-action-input {
	width: 100%;
	box-sizing: border-box;
	font-family: inherit;
	font-size: 13px;
	line-height: 1.45;
	color: var(--text);
	background: var(--surface);
	border: 1px solid var(--border-2);
	border-radius: 7px;
	padding: 6px 9px;
	outline: none;
	resize: vertical;
	transition: border-color 0.12s, box-shadow 0.12s;
}
.jv-action-input:focus {
	border-color: var(--cta);
	box-shadow: 0 0 0 3px var(--cta-bg);
}
.jv-action-sel {
	cursor: pointer;
	appearance: auto;
}
.jv-draft-body {
	flex: 1;
	overflow-y: auto;
	padding: 14px 16px;
	display: flex;
	flex-direction: column;
	gap: 14px;
}
.jv-draft-toast {
	font-size: 12px;
	color: var(--cta);
	background: var(--cta-bg);
	border: 1px solid var(--cta-bd);
	border-radius: 8px;
	padding: 7px 11px;
}
.jv-draft-fields {
	display: grid;
	grid-template-columns: 1fr 1fr;
	gap: 10px 12px;
}
.jv-draft-fld label {
	display: block;
	font-size: 10.5px;
	font-weight: 650;
	letter-spacing: 0.06em;
	text-transform: uppercase;
	color: var(--text-3);
	margin-bottom: 4px;
}
.jv-draft-fld .jv-req {
	color: var(--red);
}
/* :deep so a field drawn inside a child control (DateControl's picker input, #833) is marked too. */
.jv-draft-fld.missing :deep(.jv-action-input) {
	border-color: var(--amber-bd);
}
/* a value the save refused (a bad option or link): marked until the next save */
.jv-draft-fld.invalid :deep(.jv-action-input) {
	border-color: var(--red);
}
.jv-draft-fld.changed :deep(.jv-action-input) {
	border-color: var(--cta-bd);
	background: var(--cta-bg);
}
.jv-draft-ctl {
	position: relative;
}
/* A read_only main field is shown, not editable: a muted static value (mirrors the
   child-grid jv-grid-ro treatment) so the user can't type into a field the confirm
   would discard. A proposed read_only value still shows here for review. */
.jv-draft-ro {
	display: inline-block;
	padding: 4px 0;
	color: var(--text-2);
	word-break: break-word;
}
.jv-rows-changed {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 6px 10px;
	padding: 6px 10px;
	margin-bottom: 6px;
	border-radius: 6px;
	border: 1px solid var(--cta-bd);
	background: var(--cta-bg);
	color: var(--cta);
	font-size: 12.5px;
	overflow-wrap: anywhere;
}
.jv-rows-changed-open {
	background: none;
	border: 1px solid var(--cta-bd);
	border-radius: 7px;
	color: var(--cta);
	font-weight: 600;
	font-size: 12.5px;
	cursor: pointer;
	padding: 2px 10px;
	min-height: 32px;
}
.jv-rows-changed-open:focus-visible {
	outline: 2px solid var(--cta);
	outline-offset: 1px;
}
.jv-rows-removed {
	padding: 6px 10px;
	margin-bottom: 6px;
	border-radius: 6px;
	border: 1px solid var(--red-bd);
	background: var(--red-bg);
	color: var(--red);
	font-size: 12px;
}
.jv-draft-table-title {
	font-size: 12px;
	font-weight: 650;
	color: var(--text-2);
	margin-bottom: 6px;
}
.jv-draft-gridwrap {
	overflow-x: auto;
	border: 1px solid var(--border);
	border-radius: 9px;
}
.jv-grid {
	width: 100%;
	border-collapse: collapse;
	font-size: 13px;
}
.jv-grid th {
	font-size: 10.5px;
	font-weight: 650;
	letter-spacing: 0.05em;
	text-transform: uppercase;
	color: var(--text-3);
	text-align: left;
	padding: 7px 8px;
	border-bottom: 1px solid var(--border-2);
	background: var(--surface-1);
}
.jv-grid td {
	padding: 5px 6px;
	border-bottom: 1px solid var(--border);
	position: relative;
	min-width: 90px;
}
/* An open row (DraftRowBlock in place): one cell across the whole row, its card pinned
   to the left at the scroller's visible width (the gridwrap is an inline-size
   container), so it fits the panel however far the grid is scrolled sideways. */
.jv-draft-gridwrap {
	container-type: inline-size;
}
.jv-grid td.jv-grid-opencell {
	padding: 0;
	min-width: 0;
	background: var(--surface);
}
.jv-grid-opencell > :deep(.jv-rowform-block) {
	position: sticky;
	left: 0;
	width: 100cqi;
	box-sizing: border-box;
}
.jv-grid td .jv-action-input {
	width: 100%;
	box-sizing: border-box;
}
.jv-grid-ro {
	color: var(--text-3);
}
.jv-grid-x {
	width: 1%;
	white-space: nowrap;
	min-width: 0 !important;
}
/* The leading cell: row number + the row-form toggle, first in the row so they are on
   screen at scrollLeft 0 on a phone without sticky CSS. At most 96px; the extra
   specificity beats `.jv-grid td { min-width: 90px }`. The badges wrap under the arrow
   rather than widening it. */
.jv-grid td.jv-grid-lead,
.jv-grid th.jv-grid-lead {
	width: 96px;
	max-width: 96px;
	min-width: 0;
	box-sizing: border-box;
}
.jv-grid th.jv-grid-lead {
	position: relative; /* anchors the visually-hidden "Row" label */
}
/* Inside the cell, not on it: a flex td would leave table layout. */
.jv-grid-lead-in {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 4px;
}
.jv-grid-num {
	min-width: 1.4em;
	font-size: 11.5px;
	font-variant-numeric: tabular-nums;
	color: var(--text-3);
}
.jv-grid-lead .jv-grid-more {
	flex-wrap: wrap;
	max-width: 100%;
	box-sizing: border-box;
}
.jv-grid-acts {
	display: inline-flex;
	align-items: center;
	gap: 6px;
}
/* Opens a row's full form (DraftRowForm, below the grid). A ~32px target, kept
   apart from Remove so a thumb aimed at one does not hit the other. */
.jv-grid-more,
.jv-grid-del {
	min-width: 32px;
	min-height: 32px;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	gap: 3px;
}
.jv-grid-more {
	background: none;
	border: 1px solid var(--border);
	color: var(--text-3);
	cursor: pointer;
	padding: 2px 6px;
	border-radius: 7px;
}
.jv-grid-more:hover,
.jv-grid-more[aria-expanded="true"] {
	color: var(--cta);
	background: var(--surface-1);
}
.jv-grid-more-warn {
	border-color: var(--amber-bd);
}
.jv-grid-badge {
	font-size: 10.5px;
	font-weight: 650;
	line-height: 16px;
	min-width: 16px;
	padding: 0 4px;
	border-radius: 8px;
	background: var(--surface-1);
	color: var(--text-2);
}
.jv-grid-badge-warn {
	background: var(--amber-bg);
	color: var(--amber);
}
.jv-grid-more:focus-visible,
.jv-grid-del:focus-visible {
	outline: 2px solid var(--cta);
	outline-offset: 1px;
}
.jv-grid-del {
	background: none;
	border: none;
	color: var(--text-3);
	cursor: pointer;
	padding: 4px 6px;
	border-radius: 6px;
}
.jv-grid-del:hover {
	color: var(--red);
	background: var(--red-bg);
}
.jv-draft-addrow {
	align-self: flex-start;
	margin-top: 8px;
	background: none;
	border: none;
	color: var(--cta);
	font-weight: 600;
	font-size: 12.5px;
	cursor: pointer;
	padding: 4px 2px;
}
.jv-draft-totals {
	display: flex;
	flex-wrap: wrap;
	align-items: flex-end;
	gap: 10px 14px;
	padding: 12px 14px;
	border: 1px solid var(--border);
	border-radius: 10px;
	background: var(--surface-1);
}
.jv-draft-total-fld {
	display: flex;
	flex-direction: column;
	flex: 1 1 130px;
	min-width: 120px;
}
.jv-draft-total-fld label {
	display: block;
	font-size: 10.5px;
	font-weight: 650;
	letter-spacing: 0.06em;
	text-transform: uppercase;
	color: var(--text-3);
	margin-bottom: 4px;
}
.jv-draft-total-ctl {
	position: relative;
}
/* read-only: muted fill, no caret, a lock glyph — clearly not an editable field */
.jv-draft-total-input {
	width: 100%;
	box-sizing: border-box;
	background: var(--surface-2);
	color: var(--text);
	font-weight: 650;
	font-variant-numeric: tabular-nums;
	cursor: default;
	padding-right: 28px;
}
.jv-draft-total-input:focus {
	border-color: var(--border-2);
	box-shadow: none;
}
.jv-draft-total-lock {
	position: absolute;
	right: 9px;
	top: 50%;
	transform: translateY(-50%);
	color: var(--text-3);
	pointer-events: none;
}
.jv-draft-parked {
	padding: 10px 12px;
	border: 1px solid var(--border);
	border-radius: 8px;
	color: var(--text-2);
	font-size: 13px;
}
.jv-draft-parked.is-empty {
	padding: 0;
	border: 0;
	margin-top: 0 !important;
}
.jv-draft-est {
	flex-basis: 100%;
	margin: 0;
	color: var(--text-3);
	font-size: 11px;
}
@media (max-width: 700px) {
	.jv-draft-fields {
		grid-template-columns: 1fr;
	}
}

style.DraftPreview:
.dp-overlay {
	position: absolute;
	inset: 0;
	z-index: 61;
	background: rgba(15, 15, 22, 0.32);
	display: flex;
	justify-content: flex-end;
}
.jv-dark .dp-overlay {
	background: rgba(0, 0, 0, 0.5);
}
.dp-panel {
	position: relative;
	/* Of the overlay (the chat column), never the viewport: a definite max-width
	   also caps the flex item's automatic minimum, so a nowrap grid cannot hold
	   the panel wider than the column and push it under the sidebar (#776). */
	max-width: 92%;
	height: 100%;
	background: var(--surface);
	border-left: 1px solid var(--border);
	display: flex;
	flex-direction: column;
	box-shadow: -14px 0 44px rgba(20, 20, 30, 0.14);
}
.dp-panel:focus {
	outline: none;
}
/* Drag handle on the inner (left) edge; 1px rule that lights up on hover/drag. */
.dp-resizer {
	position: absolute;
	left: 0;
	top: 0;
	z-index: 3;
	height: 100%;
	width: 8px;
	margin-left: -4px;
	cursor: col-resize;
}
.dp-resizer::before {
	content: "";
	position: absolute;
	left: 4px;
	top: 0;
	height: 100%;
	width: 1px;
	background: var(--cta);
	opacity: 0;
	transition: opacity 0.15s ease;
}
.dp-resizer:hover::before,
.dp-resizer-active::before {
	opacity: 1;
}
.dp-panel-resizing {
	user-select: none;
}
:global(body.dp-resizing-body) {
	cursor: col-resize;
	user-select: none;
}
.dp-head {
	display: flex;
	align-items: center;
	gap: 9px;
	padding: 11px 12px 11px 14px;
	border-bottom: 1px solid var(--border);
	flex: none;
}
.dp-head svg {
	flex: none;
}
.dp-title {
	font-size: 14px;
	font-weight: 600;
	color: var(--text);
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
	flex: 1;
	min-width: 0;
}
.dp-badge {
	font-size: 10px;
	font-weight: 650;
	letter-spacing: 0.08em;
	text-transform: uppercase;
	color: var(--amber);
	background: var(--amber-bg);
	border: 1px solid var(--amber-bd);
	border-radius: 99px;
	padding: 3px 9px;
	flex: none;
}
.dp-badge-upd {
	color: var(--cta);
	background: var(--cta-bg);
	border-color: var(--cta-bd);
}
.dp-close {
	background: none;
	border: none;
	color: var(--text-3);
	cursor: pointer;
	padding: 4px;
	border-radius: 6px;
	display: flex;
}
.dp-close:hover {
	background: var(--surface-2);
	color: var(--text);
}
.dp-body {
	flex: 1;
	overflow-y: auto;
	padding: 14px 16px;
	display: flex;
	flex-direction: column;
	gap: 14px;
}
.dp-headline {
	font-size: 13.5px;
	font-weight: 600;
	color: var(--text);
}
.dp-fields {
	display: grid;
	grid-template-columns: max-content 1fr;
	gap: 6px 16px;
	margin: 0;
}
.dp-fields dt {
	font-size: 10.5px;
	font-weight: 650;
	letter-spacing: 0.06em;
	text-transform: uppercase;
	color: var(--text-3);
	align-self: center;
}
.dp-fields dd {
	margin: 0;
	overflow-wrap: anywhere;
	font-size: 13.5px;
	color: var(--text);
}
.dp-req {
	color: var(--red);
}
.dp-changed .dp-old {
	color: var(--text-3);
	text-decoration: line-through;
}
.dp-changed .dp-arrow {
	color: var(--text-3);
}
.dp-changed .dp-new {
	color: var(--green);
	font-weight: 600;
}
.dp-table {
	border: 1px solid var(--border);
	border-radius: 8px;
	overflow: hidden;
}
.dp-table-title {
	padding: 7px 10px;
	background: var(--surface-2);
	font-size: 12px;
	font-weight: 650;
	color: var(--text-2);
}
.dp-gridwrap {
	overflow-x: auto;
}
.dp-grid {
	width: 100%;
	border-collapse: collapse;
	font-size: 12.5px;
}
.dp-grid th {
	text-align: left;
	padding: 6px 10px;
	color: var(--text-3);
	font-weight: 600;
	border-bottom: 1px solid var(--border);
	white-space: nowrap;
}
.dp-grid td {
	padding: 5px 10px;
	color: var(--text);
	border-bottom: 1px solid var(--border);
	white-space: nowrap;
}
.dp-grid tbody tr:last-child td {
	border-bottom: none;
}
.dp-grid td.dp-computed {
	color: var(--text-2);
	font-variant-numeric: tabular-nums;
}
/* A row's filled fields outside the grid (its full form). */
.dp-rowmore {
	margin-top: 6px;
	font-size: 12.5px;
	color: var(--text-2);
}
.dp-rowmore summary {
	cursor: pointer;
	color: var(--text-3);
	padding: 2px 0;
}
.dp-rowmore summary:focus-visible {
	outline: 2px solid var(--cta);
	outline-offset: 2px;
	border-radius: 4px;
}
.dp-rowmore-list {
	display: grid;
	grid-template-columns: minmax(100px, max-content) minmax(0, 1fr);
	gap: 4px 12px;
	margin: 6px 0 0 14px;
}
.dp-rowmore-list dt {
	color: var(--text-3);
}
.dp-rowmore-list dd {
	margin: 0;
	color: var(--text);
	overflow-wrap: anywhere;
}
.dp-rowmore-also {
	margin: 8px 0 0 14px;
	font-size: 11.5px;
	color: var(--text-3);
}
.dp-computed-note {
	padding: 6px 0 0;
	font-size: 11.5px;
	color: var(--text-3);
}
.dp-empty {
	font-size: 12.5px;
	color: var(--text-3);
}
.dp-foot {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 8px;
	padding: 11px 14px;
	border-top: 1px solid var(--border);
	background: var(--surface-1);
	flex: none;
}
.dp-btn {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	height: 28px;
	padding: 0 10px;
	line-height: 1;
	white-space: nowrap;
	flex: 0 0 auto;
	border-radius: 8px;
	font-size: 13px;
	font-weight: 500;
	border: 1px solid var(--border);
	background: var(--surface);
	color: var(--text);
	cursor: pointer;
}
.dp-btn:hover {
	background: var(--surface-2);
}
.dp-btn-primary {
	background: var(--cta);
	border-color: var(--cta);
	color: var(--cta-fg);
}
.dp-btn-primary:hover {
	filter: brightness(1.05);
}
.dp-btn-primary:disabled {
	opacity: 0.55;
	cursor: not-allowed;
}
.dp-slide-enter-active,
.dp-slide-leave-active {
	transition: opacity 0.18s ease;
}
.dp-slide-enter-active .dp-panel,
.dp-slide-leave-active .dp-panel {
	transition: transform 0.22s cubic-bezier(0.4, 0, 0.2, 1);
}
.dp-slide-enter-from,
.dp-slide-leave-to {
	opacity: 0;
}
.dp-slide-enter-from .dp-panel,
.dp-slide-leave-to .dp-panel {
	transform: translateX(100%);
}

style.DraftLinkMenu:
.jv-action-linkmenu {
	position: fixed;
	z-index: 91;
	box-sizing: border-box;
	background: var(--surface);
	border: 1px solid var(--border-2);
	border-radius: 9px;
	box-shadow: 0 8px 24px rgba(20, 20, 30, 0.14);
	padding: 4px;
	overflow-y: auto;
	font-family: "Inter", system-ui, sans-serif;
}
.jv-action-linkmenu button {
	display: block;
	width: 100%;
	text-align: left;
	padding: 7px 9px;
	background: transparent;
	border: none;
	border-radius: 6px;
	font-family: inherit;
	font-size: 12.5px;
	color: var(--text-2);
	overflow-wrap: anywhere;
	cursor: pointer;
}
.jv-action-linkmenu button:hover,
.jv-action-linkmenu button:focus-visible {
	background: var(--surface-2);
	color: var(--text);
}

style.Sheet:
.jv-sheet-root {
	position: fixed;
	inset: 0;
	z-index: 60;
	display: flex;
	flex-direction: column;
	justify-content: flex-end;
}
.jv-sheet-scrim {
	position: absolute;
	inset: 0;
	background: var(--scrim);
}
.jv-sheet {
	position: relative;
	max-height: 88dvh;
	display: flex;
	flex-direction: column;
	background: var(--card);
	border-radius: 22px 22px 0 0;
	border-top: 1px solid var(--border);
	overflow: hidden;
}
.jv-sheet-grab {
	width: 38px;
	height: 4px;
	margin: 8px auto 6px;
	flex: none;
	border-radius: 999px;
	background: var(--card3);
}

.jv-sheet-enter-active,
.jv-sheet-leave-active {
	transition: opacity 0.18s ease;
}
.jv-sheet-enter-active .jv-sheet,
.jv-sheet-leave-active .jv-sheet {
	transition: transform 0.24s cubic-bezier(0.32, 0.72, 0, 1);
}
.jv-sheet-enter-from,
.jv-sheet-leave-to {
	opacity: 0;
}
.jv-sheet-enter-from .jv-sheet,
.jv-sheet-leave-to .jv-sheet {
	transform: translateY(100%);
}
@media (prefers-reduced-motion: reduce) {
	.jv-sheet-enter-active .jv-sheet,
	.jv-sheet-leave-active .jv-sheet {
		transition: none;
	}
}
